-- ==================
-- MONITOR CONFIG
-- ==================
-- monitor = monitor_name, resolution@refresh_rate, position, scale, vrr, <vrr_value> (0: off, 1: always on, 2: on with fullscreen apps)
-- set vrr to override the global vrr setting in misc.conf

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local mainMonitor = "DP-1"
local secondMonitor = "DP-2"

hl.monitor({
    output = "$mainMonitor",
    mode = "2560x1440@280",
    position = "1920x0",
    scale = "1",
    vrr = 2,
})

hl.monitor({
    output = "$secondMonitor",
    mode = "1920x1080@240",
    position = "0x0",
    scale = "1",
    vrr = 2,
    bitdepth = 8,
})

return {
	mainMonitor = mainMonitor,
	secondMonitor = secondMonitor
}
